def step_action(self, action):
    if action is None:  # simulation without action
        pass
    elif isinstance(action, np.ndarray):
        self.agent.set_action(action)
    elif isinstance(action, dict):
        if action["control_mode"] != self.agent.control_mode:
            self.agent.set_control_mode(action["control_mode"])
        self.agent.set_action(action["action"])
    else:
        raise TypeError(type(action))

    self._before_control_step()
    for _ in range(self._sim_steps_per_control):
        self.agent.before_simulation_step()
        self._scene.step()
        self._after_simulation_step()

def get_done(self, info: dict, **kwargs):
    # NOTE(jigu): cast to bool explicitly for gym >=0.24
    return bool(info["success"])

def before_simulation_step(self):
    if self.balance_passive_force:
        qf = self.articulation.compute_passive_force(external=False)
    else:
        qf = np.zeros(self.articulation.dof)
    for controller in self.controllers.values():
        ret = controller.before_simulation_step()
        if ret is not None and "qf" in ret:
            qf = qf + ret["qf"]
    self.articulation.set_qf(qf)

def set_action(self, action: np.ndarray):
    action = self._preprocess_action(action)

    self._step = 0
    self._start_qpos = self.qpos

    if self.config.use_target:
        prev_ee_pose_at_base = self._target_pose
    else:
        prev_ee_pose_at_base = self.ee_pose_at_base

    self._target_pose = self.compute_target_pose(prev_ee_pose_at_base, action)
    self._target_qpos = self.compute_ik(self._target_pose)
    if self._target_qpos is None:
        self._target_qpos = self._start_qpos

    if self.config.interpolate:
        self._step_size = (self._target_qpos - self._start_qpos) / self._sim_steps
    else:
        self.set_drive_targets(self._target_qpos)

def before_simulation_step(self):
    self._step += 1

    # Compute the next target
    if self.config.interpolate:
        targets = self._start_qpos + self._step_size * self._step
        self.set_drive_targets(targets)

def compute_target_pose(self, prev_ee_pose_at_base, action):
    # Keep the current rotation and change the position
    if self.config.use_delta:
        delta_pose = sapien.Pose(action)

        if self.config.frame == "base":
            target_pose = delta_pose * prev_ee_pose_at_base
        elif self.config.frame == "ee":
            target_pose = prev_ee_pose_at_base * delta_pose
        else:
            raise NotImplementedError(self.config.frame)
    else:
        assert self.config.frame == "base", self.config.frame
        target_pose = sapien.Pose(action)

    return target_pose

def set_action(self, action: np.ndarray):
    action = self._preprocess_action(action)

    self._step = 0
    self._start_qpos = self.qpos

    if self.config.use_delta:
        if self.config.use_target:
            self._target_qpos = self._target_qpos + action
        else:
            self._target_qpos = self._start_qpos + action
    else:
        # Compatible with mimic
        self._target_qpos = np.broadcast_to(action, self._start_qpos.shape)

    if self.config.interpolate:
        self._step_size = (self._target_qpos - self._start_qpos) / self._sim_steps
    else:
        self.set_drive_targets(self._target_qpos)

def before_simulation_step(self):
    self._step += 1

    # Compute the next target
    if self.config.interpolate:
        targets = self._start_qpos + self._step_size * self._step
        self.set_drive_targets(targets)
